```typescript
import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { axe, toHaveNoViolations } from 'jest-axe';
import { Checkout } from './Checkout';
import { CartProvider } from './CartContext';
import { PaymentProvider } from './PaymentContext';

expect.extend(toHaveNoViolations);

const mockCart = {
  items: [{ id: '1', name: 'Widget', price: 29.99 }],
  total: 29.99,
  clearCart: vi.fn()
};

const mockPayment = {
  processPayment: vi.fn().mockResolvedValue({ orderId: 'ORD-123' })
};

const renderCheckout = (props = {}) => {
  return render(
    <CartProvider value={mockCart}>
      <PaymentProvider value={mockPayment}>
        <Checkout {...props} />
      </PaymentProvider>
    </CartProvider>
  );
};

describe('Checkout - The Path Through Chaos', () => {
  describe('Happy Path - Complete Flow', () => {
    it('guides the wanderer from shipping to confirmation', async () => {
      const user = userEvent.setup();
      const onComplete = vi.fn();
      renderCheckout({ onComplete });

      // Shipping step
      await user.type(screen.getByLabelText(/street/i), '123 Fury Road');
      await user.type(screen.getByLabelText(/city/i), 'Citadel');
      await user.selectOptions(screen.getByLabelText(/state/i), 'CA');
      await user.type(screen.getByLabelText(/zip/i), '90210');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      // Payment step
      await user.type(screen.getByLabelText(/card number/i), '4111111111111111');
      await user.type(screen.getByLabelText(/expiry/i), '12/25');
      await user.type(screen.getByLabelText(/cvv/i), '123');
      await user.type(screen.getByLabelText(/name on card/i), 'Max Rockatansky');
      await user.click(screen.getByRole('button', { name: /review order/i }));

      // Review & confirm
      expect(screen.getByText(/widget/i)).toBeInTheDocument();
      await user.click(screen.getByRole('button', { name: /place order/i }));

      await waitFor(() => {
        expect(screen.getByText(/ORD-123/)).toBeInTheDocument();
      });
      expect(onComplete).toHaveBeenCalledWith('ORD-123');
    });
  });

  describe('Validation - The Gates Hold', () => {
    it('demands valid ZIP code format', async () => {
      const user = userEvent.setup();
      renderCheckout();

      await user.type(screen.getByLabelText(/zip/i), 'XXXXX');
      await user.click(screen.getByRole('button', { name: /continue/i }));

      expect(screen.getByRole('alert')).toHaveTextContent(/valid zip/i);
    });
  });

  describe('Edge Cases - Everyone Dies Here', () => {
    it('shows empty cart message when cart abandoned', () => {
      render(
        <CartProvider value={{ items: [], total: 0, clearCart: vi.fn() }}>
          <PaymentProvider value={mockPayment}>
            <Checkout />
          </PaymentProvider>
        </CartProvider>
      );

      expect(screen.getByRole('alert')).toHaveTextContent(/cart is empty/i);
    });
  });

  describe('Accessibility - All May Pass', () => {
    it('has no accessibility violations', async () => {
      const { container } = renderCheckout();
      expect(await axe(container)).toHaveNoViolations();
    });
  });
});
```

